cd /app && mkdir -p output && cat > output/styles.css <<'EOF'
:root {
  --bg: #f5f5f7;
  --surface: #ffffff;
  --surface-2: #fbfbfd;
  --text: #1d1d1f;
  --muted: #6e6e73;
  --accent: #0066cc;
  --border: #d2d2d7;
  --radius-lg: 24px;
  --radius-md: 18px;
  --shadow: 0 12px 32px rgba(0, 0, 0, 0.08);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: "SF Pro Display", "SF Pro Text", "Helvetica Neue", Arial, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.35;
}

a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }

.top-nav {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(245, 245, 247, 0.9);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid rgba(0,0,0,0.06);
}
.top-nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 12px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
}
.brand { font-weight: 700; letter-spacing: 0.2px; color: var(--text); }
.main-links { display: flex; gap: 18px; flex-wrap: wrap; }
.main-links a { color: var(--text); font-size: 14px; }

.page-wrap { max-width: 1200px; margin: 0 auto; padding: 28px 20px 80px; }
.hero-title {
  font-size: clamp(40px, 6vw, 56px);
  line-height: 1.05;
  margin: 0;
  font-weight: 700;
}
.hero-subtitle {
  margin: 14px 0 0;
  font-size: clamp(19px, 2.2vw, 28px);
  color: var(--muted);
  font-weight: 400;
}

.product-category-bar {
  margin: 30px 0 10px;
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding: 6px 2px 10px;
}
.product-category-item {
  min-width: 105px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 12px 10px;
  text-align: center;
}
.product-icon {
  width: 48px;
  height: 38px;
  border-radius: 8px;
  margin: 0 auto 8px;
  background: linear-gradient(135deg, #dfe9f9, #eef2f8);
}
.product-category-item p { margin: 0; font-size: 12px; }

.section { margin-top: 44px; }
.section h2 { font-size: clamp(28px, 4vw, 40px); margin: 0 0 14px; }
.section p.lead { margin: 0 0 16px; color: var(--muted); }

.carousel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 14px;
}
.carousel-nav { display: flex; gap: 8px; }
.carousel-btn {
  width: 34px;
  height: 34px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface);
  cursor: pointer;
  font-size: 16px;
}

.carousel {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  scroll-behavior: smooth;
  padding-bottom: 6px;
}
.carousel-card {
  min-width: 260px;
  max-width: 260px;
  background: var(--surface);
  border-radius: var(--radius-md);
  padding: 18px;
  border: 1px solid rgba(0,0,0,0.05);
  box-shadow: 0 6px 16px rgba(0,0,0,0.05);
}
.card-image {
  height: 125px;
  border-radius: 12px;
  margin-bottom: 14px;
}
.grad-cool { background: linear-gradient(135deg, #dbe8ff, #f4f8ff); }
.grad-warm { background: linear-gradient(135deg, #fff0e1, #fff8f1); }
.grad-neutral { background: linear-gradient(135deg, #ebedf3, #f7f8fb); }
.carousel-card h3 { margin: 0 0 6px; font-size: 22px; }
.carousel-card p { margin: 0 0 7px; color: var(--muted); font-size: 14px; }
.price { font-weight: 600; color: var(--text) !important; }

.grid-showcase {
  margin-top: 20px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}
.hero-tile {
  min-height: 410px;
  border-radius: var(--radius-lg);
  padding: 30px;
  background: var(--surface);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.hero-tile-image {
  height: 190px;
  border-radius: 16px;
  margin-bottom: 18px;
}
.hero-tile h3 { margin: 0 0 8px; font-size: 32px; }
.hero-tile p { margin: 0 0 14px; color: var(--muted); }
.cta-row { display: flex; gap: 16px; font-size: 15px; }

.tabs-row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}
.tab-btn {
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  border-radius: 999px;
  padding: 9px 16px;
  cursor: pointer;
}
.tab-btn.active { background: #1d1d1f; color: #fff; border-color: #1d1d1f; }
.tab-panel { display: none; }
.tab-panel.active { display: block; }

.sticky-section-nav {
  position: sticky;
  top: 52px;
  z-index: 30;
  background: rgba(245,245,247,0.95);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(0,0,0,0.05);
  border-radius: 999px;
  padding: 8px 10px;
  margin: 24px 0;
  overflow-x: auto;
}
.sticky-section-nav .links {
  display: flex;
  gap: 14px;
  white-space: nowrap;
}

.quick-links {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.quick-links a {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 10px 16px;
  color: var(--text);
  font-size: 14px;
}

.footer {
  margin-top: 50px;
  border-top: 1px solid var(--border);
  padding-top: 20px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0,1fr));
  gap: 14px;
}
.footer-group h4 { margin: 0 0 10px; font-size: 14px; }
.footer-group a {
  display: block;
  color: var(--muted);
  margin: 0 0 6px;
  font-size: 13px;
}

@media (max-width: 960px) {
  .grid-showcase { grid-template-columns: 1fr; }
}

@media (max-width: 760px) {
  .footer-grid { display: block; }
  .footer-group {
    border-top: 1px solid var(--border);
    padding: 10px 0;
  }
  .footer-group h4 {
    margin: 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
  }
  .footer-group-links { display: none; padding-top: 8px; }
  .footer-group.open .footer-group-links { display: block; }
}
EOF

cat > output/scripts.js <<'EOF'
function attachCarousels() {
  document.querySelectorAll('[data-carousel]').forEach((carousel) => {
    const id = carousel.getAttribute('id');
    const prev = document.querySelector(`[data-prev="${id}"]`);
    const next = document.querySelector(`[data-next="${id}"]`);
    if (!prev || !next) return;
    const scrollAmount = 300;
    prev.addEventListener('click', () => carousel.scrollBy({ left: -scrollAmount, behavior: 'smooth' }));
    next.addEventListener('click', () => carousel.scrollBy({ left: scrollAmount, behavior: 'smooth' }));
  });
}

function attachTabs() {
  const tabButtons = document.querySelectorAll('[data-tab]');
  const panels = document.querySelectorAll('[data-panel]');
  tabButtons.forEach((button) => {
    button.addEventListener('click', () => {
      const target = button.getAttribute('data-tab');
      tabButtons.forEach((btn) => btn.classList.remove('active'));
      panels.forEach((panel) => panel.classList.remove('active'));
      button.classList.add('active');
      const panel = document.querySelector(`[data-panel="${target}"]`);
      if (panel) panel.classList.add('active');
    });
  });
}

function attachFooterAccordion() {
  if (window.matchMedia('(max-width: 760px)').matches) {
    document.querySelectorAll('.footer-group h4').forEach((heading) => {
      heading.addEventListener('click', () => {
        heading.parentElement.classList.toggle('open');
      });
    });
  }
}

document.addEventListener('DOMContentLoaded', () => {
  attachCarousels();
  attachTabs();
  attachFooterAccordion();
});
EOF

